     *   `item.input_audio_transcription.logprobs`
     */
    fun createRealtimeTranscriptionSession(
        clientConfig: ClientConfig,
        turnDetection: RealtimeTranscriptionSessionCreateRequestTurnDetection? = null,
        inputAudioNoiseReduction:
            RealtimeTranscriptionSessionCreateRequestInputAudioNoiseReduction? =
            null,
        inputAudioFormat: RealtimeTranscriptionSessionCreateRequestInputAudioFormatEnum? = null,
        inputAudioTranscription: AudioTranscription? = null,
        include: List<RealtimeTranscriptionSessionCreateRequestIncludeItemEnum>? = null,
        options: RequestOptions? = null,
    ): RealtimeTranscriptionSessionCreateResponse {
        return SdkClient.request<RealtimeTranscriptionSessionCreateResponse>(
                SdkClient.RequestSpec(
                    "POST",
                    "/realtime/transcription_sessions",
                    config = clientConfig,
                    body =
                        SdkClient.bodyMap(
                            "turn_detection" to (SdkClient.omitIfNull(turnDetection)),
                            "input_audio_noise_reduction" to
                                (SdkClient.omitIfNull(inputAudioNoiseReduction)),
                            "input_audio_format" to (SdkClient.omitIfNull(inputAudioFormat)),
                            "input_audio_transcription" to
                                (SdkClient.omitIfNull(inputAudioTranscription)),
                            "include" to (SdkClient.omitIfNull(include)),
                        ),
                    operationId = "createRealtimeTranscriptionSession",
                    decoder = SdkClient.ResponseDecoder.JSON,
                    options = options,
                )
            )
            .data
    }

    /**
     * Create a Realtime translation client secret with an associated translation session
     * configuration. Client secrets are short-lived tokens that can be passed to a client app, such
     * as a web frontend or mobile client, which grants access to the Realtime Translation API
     * without leaking your main API key. You can configure a custom TTL for each client secret.
     * Returns the created client secret and the effective translation session object. The client
     * secret is a string that looks…
     *
     * @param session Realtime translation session configuration. Translation sessions stream source
     *   audio in and translated audio plus transcript deltas out continuously.
     * @param expiresAfter Configuration for the client secret expiration. Expiration refers to the
