     *   itself may continue after that time once started. A secret can be used to create multiple
     *   sessions until it expires.
     */
    fun createRealtimeTranslationClientSecret(
        clientConfig: ClientConfig,
        session: RealtimeTranslationSessionCreateRequest,
        expiresAfter: RealtimeTranslationClientSecretCreateRequestExpiresAfter? = null,
        options: RequestOptions? = null,
    ): RealtimeTranslationClientSecretCreateResponse {
        return SdkClient.request<RealtimeTranslationClientSecretCreateResponse>(
                SdkClient.RequestSpec(
                    "POST",
                    "/realtime/translations/client_secrets",
                    config = clientConfig,
                    body =
                        SdkClient.bodyMap(
                            "session" to (session),
                            "expires_after" to (SdkClient.omitIfNull(expiresAfter)),
                        ),
                    operationId = "createRealtimeTranslationClientSecret",
                    decoder = SdkClient.ResponseDecoder.JSON,
                    options = options,
                    errors =
                        mapOf(
                            "400" to ErrorResponse::class.java,
                            "404" to ErrorResponse::class.java,
                            "500" to ErrorResponse::class.java,
                        ),
                )
            )
            .data
    }
